require_once __DIR__.'/../includes/auth.php';$u=require_role('business');$uid=(int)$u['id'];$cats=db()->query("SELECT id,name FROM categories WHERE is_active=1 ORDER BY name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$name=clean_text($_POST['business_name']??'',180,true,'Business name');$cat=(int)($_POST['category_id']??0);$desc=clean_text($_POST['description']??'',10000,true,'Description');$address=clean_text($_POST['address']??'',255,true,'Address');$phone=clean_text($_POST['phone']??'',25,false,'Phone');$city=clean_text($_POST['city']??'',100,true,'City');$state=clean_text($_POST['state']??'',100,true,'State');$area=clean_text($_POST['area']??'',150,false,'Area');$pin=clean_text($_POST['pincode']??'',12,false,'Pincode');if(!$cat)throw new RuntimeException('Business category is required.');if(!valid_phone_or_empty($phone))throw new RuntimeException('Phone number is invalid.');if(!valid_pincode_or_empty($pin))throw new RuntimeException('Pincode is invalid.');$validCat=false;foreach($cats as $c){if((int)$c['id']===$cat){$validCat=true;break;}}if(!$validCat)throw new RuntimeException('Business category is invalid.');$oldQ=db()->prepare('SELECT logo FROM business_profiles WHERE user_id=?');$oldQ->execute([$uid]);$oldLogo=(string)($oldQ->fetchColumn()?:'');$logo=upload_image($_FILES['logo']??[],'businesses');$slug=slugify($name).'-'.$uid;$open=nullable_time($_POST['opening_time']??null,'Opening time');$close=nullable_time($_POST['closing_time']??null,'Closing time');$min=nullable_money($_POST['price_min']??null,'Minimum price');$max=nullable_money($_POST['price_max']??null,'Maximum price');$website=validated_http_url($_POST['website']??'',255);if($min!==null&&$max!==null&&$max<$min)throw new RuntimeException('Maximum price cannot be lower than minimum price.');db()->beginTransaction();$s=db()->prepare("UPDATE users SET phone=?,city=?,state=?,area=?,pincode=? WHERE id=?");$s->execute([$phone,$city,$state,$area,$pin,$uid]);$sql="UPDATE business_profiles SET category_id=?,business_name=?,slug=?,description=?,address=?,phone=?,opening_time=?,closing_time=?,price_min=?,price_max=?,website=?".($logo?',logo=?':'')." WHERE user_id=?";$args=[$cat,$name,$slug,$desc,$address,$phone,$open,$close,$min,$max,$website];if($logo)$args[]=$logo;$args[]=$uid;db()->prepare($sql)->execute($args);db()->commit();if($logo&&$oldLogo&&$oldLogo!==$logo)delete_managed_upload($oldLogo);flash('success','Business profile updated successfully.');redirect('business/profile.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();if(isset($logo)&&$logo)delete_managed_upload($logo);$error=$e instanceof RuntimeException?$e->getMessage():'Could not update business profile.';}}
$s=db()->prepare("SELECT u.*,b.* FROM users u JOIN business_profiles b ON b.user_id=u.id WHERE u.id=?");$s->execute([$uid]);$p=$s->fetch();$pageTitle='Business Profile — LocalConnect';require __DIR__.'/../includes/header.php';?>
<div class="container py-5"><div class="row justify-content-center"><div class="col-lg-9"><div class="d-flex justify-content-between"><div><h1 class="fw-bold">Business profile</h1><p class="text-muted">Business category is required for marketplace discovery.</p></div><a class="btn btn-outline-primary align-self-start" href="<?=e(base_url('business.php?id='.$uid))?>">Public View</a></div><?php if(!empty($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="soft-card p-4"><?=csrf_field()?><div class="row g-3"><div class="col-md-8"><label class="form-label">Business name *</label><input class="form-control" name="business_name" required value="<?=e($p['business_name'])?>"></div><div class="col-md-4"><label class="form-label">Category *</label><select class="form-select" name="category_id" required><option value="">Select</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$p['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Description *</label><textarea class="form-control" rows="4" name="description" required><?=e($p['description'])?></textarea></div><div class="col-12"><label class="form-label">Address *</label><input class="form-control" name="address" required value="<?=e($p['address'])?>"></div><div class="col-md-4"><label class="form-label">City *</label><input class="form-control" name="city" required value="<?=e($p['city'])?>"></div><div class="col-md-4"><label class="form-label">State *</label><input class="form-control" name="state" required value="<?=e($p['state'])?>"></div><div class="col-md-2"><label class="form-label">Area</label><input class="form-control" name="area" value="<?=e($p['area'])?>"></div><div class="col-md-2"><label class="form-label">Pincode</label><input class="form-control" name="pincode" value="<?=e($p['pincode'])?>"></div><div class="col-md-4"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=e($p['phone'])?>"></div><div class="col-md-4"><label class="form-label">Opening time</label><input type="time" class="form-control" name="opening_time" value="<?=e((string)$p['opening_time'])?>"></div><div class="col-md-4"><label class="form-label">Closing time</label><input type="time" class="form-control" name="closing_time" value="<?=e((string)$p['closing_time'])?>"></div><div class="col-md-4"><label class="form-label">Price from ₹</label><input type="number" min="0" class="form-control" name="price_min" value="<?=e((string)$p['price_min'])?>"></div><div class="col-md-4"><label class="form-label">Price to ₹</label><input type="number" min="0" class="form-control" name="price_max" value="<?=e((string)$p['price_max'])?>"></div><div class="col-md-4"><label class="form-label">Website</label><input type="url" class="form-control" name="website" value="<?=e($p['website'])?>"></div><div class="col-12"><label class="form-label">Logo / photo</label><input type="file" class="form-control" name="logo" accept="image/jpeg,image/png,image/webp"></div><div class="col-12"><button class="btn btn-primary">Save Business Profile</button></div></div></form></div></div></div><?php require __DIR__.'/../includes/footer.php';?>
